        ].join('\n'));

        assert.equal(usage.readTokens, 600);
        assert.equal(usage.writeTokens, 60);
        assert.equal(usage.cachedTokens, 180);
        assert.equal(usage.requests, 18);
        assert.equal(usage.samples, 3);
